-- Generated existing-song metadata migration; no song/chart IDs are changed.
START TRANSACTION;
CREATE TEMPORARY TABLE existing_song_updates (
  song_id BIGINT PRIMARY KEY,
  old_song_hash VARCHAR(64), new_song_hash VARCHAR(64) NOT NULL,
  old_genre_name VARCHAR(255) NOT NULL, new_genre_name VARCHAR(255) NOT NULL,
  old_artist_name VARCHAR(255), new_artist_name VARCHAR(255) NOT NULL,
  old_jacket_url VARCHAR(512), new_jacket_url VARCHAR(512) NOT NULL
) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TEMPORARY TABLE migration_assertions (ok TINYINT NOT NULL CHECK (ok = 1));
-- Every target must still contain either its before state or its desired state.
SELECT IF(COUNT(*) = 0, 1, 0) FROM existing_song_updates u
LEFT JOIN songs s ON s.song_id = u.song_id
WHERE s.song_id IS NULL OR (NOT (s.song_hash <=> u.old_song_hash) AND NOT (s.song_hash <=> u.new_song_hash));
-- A generated hash must not belong to a non-target song.
SELECT IF(COUNT(*) = 0, 1, 0) FROM songs s JOIN existing_song_updates u ON s.song_hash = u.new_song_hash
WHERE s.song_id <> u.song_id;
UPDATE songs s JOIN existing_song_updates u ON u.song_id = s.song_id
SET
  s.song_hash = u.new_song_hash,
  s.genre_name = u.new_genre_name,
  s.artist_name = u.new_artist_name,
  s.jacket_url = u.new_jacket_url,
  s.updated_at = CURRENT_TIMESTAMP
WHERE s.song_hash <=> u.old_song_hash;
-- Verify every desired value byte-for-byte before commit.
SELECT IF(COUNT(*) = 0, 1, 0) FROM existing_song_updates u JOIN songs s ON s.song_id = u.song_id
WHERE NOT (BINARY s.song_hash <=> BINARY u.new_song_hash)
   OR NOT (BINARY s.genre_name <=> BINARY u.new_genre_name)
   OR NOT (BINARY s.artist_name <=> BINARY u.new_artist_name)
   OR NOT (BINARY s.jacket_url <=> BINARY u.new_jacket_url);
COMMIT;
